import { Kafka, CompressionTypes } from 'kafkajs';

const producer = new Kafka({ brokers: ['broker-1:9092'] }).producer({
  idempotent: true, // Guarantees in-order delivery without duplicates
});

export async function publishOrderEvent(orderId: string, eventType: string, payload: any) {
  await producer.send({
    topic: 'order-lifecycle',
    compression: CompressionTypes.GZIP,
    messages: [{
      key: orderId, // Guarantees all events for this order route to the SAME partition!
      value: JSON.stringify({ eventType, payload, timestamp: Date.now() }),
    }],
  });
}
